import pennylane as qp
from pennylane import numpy as np
np.random.seed(42)
n_wires = 4
graph = [(0, 1), (0, 3), (1, 2), (2, 3)]

def U_B(beta):
    for wire in range(n_wires):
        qp.RX(2 * beta, wires=wire)

def U_C(gamma):
    for edge in graph:
        qp.CNOT(wires=edge)
        qp.RZ(gamma, wires=edge[1])
        qp.CNOT(wires=edge)
dev = qp.device('default.qubit', wires=n_wires)

@qp.qnode(dev)
def circuit(params):
    gammas, betas = (params[0], params[1])
    for wire in range(n_wires):
        qp.Hadamard(wires=wire)
    for gamma, beta in zip(gammas, betas):
        U_C(gamma)
        U_B(beta)
    C = qp.sum(*(qp.X(w1) @ qp.X(w2) for w1, w2 in graph))
    return qp.expval(C)

def objective(params):
    """Minimize the negative of the objective function C."""
    return -0.5 * (len(graph) - circuit(params))
n_layers = 2
init_params = 0.01 * np.random.rand(2, n_layers, requires_grad=True)
opt = qp.AdagradOptimizer(stepsize=0.5)
params = init_params.copy()
steps = 40
for i in range(steps):
    params = opt.step(objective, params)
final_cut_value = -objective(params)

