import pennylane as qp
from pennylane import numpy as np
from pennylane.optimize import AdamOptimizer
np.random.seed(42)

def circle(samples, center=[0.0, 0.0], radius=np.sqrt(2 / np.pi)):
    Xvals, yvals = ([], [])
    for i in range(samples):
        x = 2 * np.random.rand(2) - 1
        y = 0
        if np.linalg.norm(x - center) < radius:
            y = 1
        Xvals.append(x)
        yvals.append(y)
    return (np.array(Xvals, requires_grad=False), np.array(yvals, requires_grad=False))

def density_matrix(state):
    return state * np.conj(state).T
label_0 = [[1], [0]]
label_1 = [[0], [1]]
state_labels = np.array([label_0, label_1], requires_grad=False)
dev = qp.device('default.qubit', wires=1)

@qp.qnode(dev)
def qcircuit(params, x, y):
    qp.Rot(*x, wires=0)
    for p in params:
        qp.Rot(*p, wires=0)
    return qp.expval(qp.Hermitian(y, wires=[0]))

def cost(params, x, y, state_labels=None):
    loss = 0.0
    dm_labels = [density_matrix(s) for s in state_labels]
    for i in range(len(x)):
        f = qcircuit(params, x[i], dm_labels[y[i]])
        loss = loss + (1 - f) ** 2
    return loss / len(x)

def predict(params, x, state_labels=None):
    dm_labels = [density_matrix(s) for s in state_labels]
    predicted = []
    for i in range(len(x)):
        fidel_function = lambda y: qcircuit(params, x[i], y)
        fidelities = [fidel_function(dm) for dm in dm_labels]
        predicted.append(np.argmax(fidelities))
    return np.array(predicted)

def accuracy_score(y_true, y_pred):
    return (y_true == y_pred).sum() / len(y_true)

def iterate_minibatches(inputs, targets, batch_size):
    for start_idx in range(0, inputs.shape[0] - batch_size + 1, batch_size):
        idxs = slice(start_idx, start_idx + batch_size)
        yield (inputs[idxs], targets[idxs])
num_training = 100
num_test = 50
Xdata, y_train = circle(num_training)
X_train = np.hstack((Xdata, np.zeros((Xdata.shape[0], 1), requires_grad=False)))
Xtest, y_test = circle(num_test)
X_test = np.hstack((Xtest, np.zeros((Xtest.shape[0], 1), requires_grad=False)))
num_layers = 3
learning_rate = 0.6
epochs = 10
batch_size = 32
opt = AdamOptimizer(learning_rate, beta1=0.9, beta2=0.999)
params = np.random.uniform(size=(num_layers, 3), requires_grad=True)
for it in range(epochs):
    for Xbatch, ybatch in iterate_minibatches(X_train, y_train, batch_size=batch_size):
        params, _, _, _ = opt.step(cost, params, Xbatch, ybatch, state_labels)
predicted_test = predict(params, X_test, state_labels)
accuracy_test = accuracy_score(y_test, predicted_test)

